    C c;
    function setUp() public { c = new C(); }
    // fuzz a non-empty bytes value to pass through calldata; version() takes no args,
    // but we include a fuzz parameter so the fuzzer can search inputs and still call the external function.
    function testFuzz_property(bytes memory junk) public {
        // Keep domain wide: no assumptions. The reference always returns "1.0.0" for any call.
        // Call the external version() and capture its return via try/catch to adhere to rules.
        bool ok;
        try c.version() returns (string memory v) {
