    function testFuzz_property(uint256 fuzz) public {
        // keep fuzz wide but avoid compiler warnings about unused variable
        if (fuzz == type(uint256).max) {
            // no-op, just to use fuzz
            fuzz = 0;
        }

        // call version and capture whether it returns a non-empty string
        bool ok;
        try c.version() returns (string memory v) {
            ok = bytes(v).length != 0;
        } catch {
            // If it reverts, consider that as not satisfying the property
            ok = false;
        }

        // The reference contract always returns a non-empty string, but the mutant returns an empty string
        assertTrue(ok);
