pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter is any address to ensure we treat inputs generally; the rule does not depend on it
    function testFuzz_property(address /*caller*/) public {
        // No assumptions: property must hold for all inputs.
        // Call the external view function version() and check it equals the canonical dotted string.
        string memory v = c.version();
        // The reference contract always returns the dotted semantic version "1.0.0" for all calls;
        // the one-statement mutant changes it to "100" which will make this assertion fail for some inputs
        // (here the input space is trivial; call itself is the fuzzed interaction).
        assertTrue(keccak256(bytes(v)) == keccak256(bytes("1.0.0")));
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // This function attempts to call setL1BlockValues from the current contract.
    // The test asserts that the call succeeds only when this contract is equal to the depositorAccount;
    // otherwise the call must revert. This captures the intended allowlist behavior.
    function checkSetL1BlockValues(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        // Prepare calldata and perform low-level call so we can detect revert as a boolean.
        // Build function selector and abi-encode the arguments to call c.setL1BlockValues(...) externally.
        bytes memory data = abi.encodeWithSelector(
            bytes4(keccak256("setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)")),
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        // Perform the external call to c and capture success boolean.
        (bool success, ) = address(c).call(data);

        // Query the declared depositorAccount from c (public getter)
        address depositor = c.depositorAccount();

        // If this contract is the depositor, the call must succeed; otherwise the call must revert.
        // This single assert distinguishes the original (only depositor allowed) from the mutant (everyone except depositor allowed).
        assert((address(this) == depositor) == success);
    }

    // allow receiving ETH if needed by tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        // We must call setL1BlockValues from the provided caller. Use low-level call to set msg.sender.
        // Prepare calldata for setL1BlockValues with arbitrary args (values don't matter for the access check).
        bytes memory data = abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            uint64(1), uint64(2), uint256(3), bytes32(4), uint64(5), bytes32(6), uint256(7), uint256(8)
        );
        // perform call as 'caller' by using call with value 0 from this contract is not possible to change msg.sender,
        // but we can simulate by requiring that when this contract calls, the behavior observed depends solely on msg.sender == depositorAccount.
        // The general rule can be stated in terms of whether the call reverts when this contract (the test) calls: since in P only the depositorAccount can call,
        // a call from this contract should revert unless this contract's address equals depositorAccount. So we use that.
        bool reverted;
        try c.setL1BlockValues(uint64(1), uint64(2), uint256(3), bytes32(4), uint64(5), bytes32(6), uint256(7), uint256(8)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Assert the general rule: the call reverts iff address(this) is not the depositorAccount.
        // We cannot read depositorAccount directly if it were non-public, but in C it is public, so we can call it.
        address depositor = c.depositorAccount();
        assert(reverted == (address(this) != depositor));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // precondition: caller is any address (no restriction)
        bool reverted;
        // perform the call from this contract context; simulate caller by requiring msg.sender equality is not possible here,
        // but the distinction between depositorAccount and others is observable via revert boolean when this contract calls.
        // We therefore require that the provided `caller` equals address(this) to express rule over who is calling —
        // the test will assert that if caller equals c.depositorAccount() then call does NOT revert, otherwise it DOES revert.
        // Ensure the parameter aligns with actual caller for the logical assertion.
        require(caller == address(this), "caller must be this contract to perform the call");
        try c.setL1BlockValues(
            uint64(1), uint64(2), uint256(3), bytes32(0), uint64(5), bytes32(0), uint256(7), uint256(8)
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Assert the general rule: call succeeds exactly when this contract is the depositorAccount of c
        // i.e., reverted == (address(this) != c.depositorAccount())
        assert(reverted == (address(this) != c.depositorAccount()));
    }
    receive() external payable {}
}

