pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the depositorAccount value stored in the contract (as an address cast from uint160), and an arbitrary caller
    function testFuzz_property(address fuzzDepositorAccount, address caller) public {
        // keep addresses wide but avoid zero address which might be considered special
        vm.assume(fuzzDepositorAccount != address(0));
        vm.assume(caller != address(0));

        // store the fuzzed depositorAccount into the contract's public variable via low-level write to its storage slot
        // We cannot use vm.store (forbidden), but depositorAccount is public and has no setter; however the reference contract
        // exposes depositorAccount as a public variable so we can simulate setting it by deploying a short helper that calls
        // into a setter—since contract C has no setter, we instead reason: the difference arises when depositorAccount != DEPOSITOR_ACCOUNT.
        // To induce that state, we'll deploy a tiny proxy that calls setL1BlockValues with 'caller' as msg.sender while we change
        // depositorAccount by constructing C with its storage already different is impossible here; instead we will exploit that
        // depositorAccount is a public field we can set by making a call that writes to it if such function existed. Since it does not,
        // we simulate the admissible environment: the property we assert only reads depositorAccount getter and compares call success
        // for caller==depositorAccount. We therefore require the fuzzer to supply fuzzDepositorAccount and we will check the
        // behavior of c when we impersonate that address.

        // The deciding difference: on the reference, a call from depositorAccount should be allowed (succeed); on the mutant,
        // only DEPOSITOR_ACCOUNT (a constant) is allowed. So pick inputs where fuzzDepositorAccount != DEPOSITOR_ACCOUNT to let
        // the mutant differ. We cannot modify the contract's storage to set depositorAccount, but we can rely on the public getter
        // depositorAccount being readable; however since it's initialized zero in the deployed contract, we will instead treat
        // fuzzDepositorAccount as the caller we will use and assert behavior assuming depositorAccount equals that caller. To ensure
        // the reference contract treats that caller as depositorAccount we need depositorAccount to equal caller; because we can't set it,
        // we instead choose the universal property: for any caller address A, the reference accepts calls when msg.sender equals depositorAccount
        // and rejects otherwise. We'll observe this by comparing two calls: one from address X and one from a different address Y.

        // Choose two distinct addresses via fuzzer inputs: caller and another.
        address other = address(uint160(uint256(keccak256(abi.encodePacked(caller, uint256(1))))));
        vm.assume(other != caller);

        // Try call from caller
        bool okCaller;
        vm.prank(caller);
        try c.setL1BlockValues({
            _number: 1,
            _timestamp: 1,
            _basefee: 1,
            _hash: bytes32(0),
            _sequenceNumber: 1,
            _batcherHash: bytes32(0),
            _l1FeeOverhead: 1,
            _l1FeeScalar: 1
        }) {
            okCaller = true;
        } catch {
            okCaller = false;
        }

        // Try call from other
        bool okOther;
        vm.prank(other);
        try c.setL1BlockValues({
            _number: 1,
            _timestamp: 1,
            _basefee: 1,
            _hash: bytes32(0),
            _sequenceNumber: 1,
            _batcherHash: bytes32(0),
            _l1FeeOverhead: 1,
            _l1FeeScalar: 1
        }) {
            okOther = true;
        } catch {
            okOther = false;
        }

        // Exactly one assertion: On the reference contract, calls from the stored depositorAccount succeed and others fail.
        // We assert that okCaller == okOther is false whenever caller != other AND one of them equals the on-chain depositorAccount.
        // To make this a universal property readable from c: read depositorAccount getter and check that exactly the address equal to it succeeds.

        address onchainDepositor = c.depositorAccount();

        // The universal property: for any caller addresses, success == (msg.sender == onchainDepositor)
        // We assert that the observed okCaller equals (caller == onchainDepositor) and okOther equals (other == onchainDepositor)
        assertTrue(okCaller == (caller == onchainDepositor) && okOther == (other == onchainDepositor));
    }
}

