pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to find one that is not the depositorAccount
    function testFuzz_property(address caller) public {
        // Keep wide domain but avoid the zero address being special (still allowed).
        // We want a caller that is likely not equal to c.depositorAccount()
        // No tight assumptions so fuzzer can find differing addresses.

        // Make a call from `caller` to setL1BlockValues and capture whether it reverted.
        bool ok;
        // prepare some arbitrary arguments (they don't affect the require check)
        uint64 _number = 1;
        uint64 _timestamp = 2;
        uint256 _basefee = 3;
        bytes32 _hash = bytes32(uint256(4));
        uint64 _sequenceNumber = 5;
        bytes32 _batcherHash = bytes32(uint256(6));
        uint256 _l1FeeOverhead = 7;
        uint256 _l1FeeScalar = 8;

        vm.prank(caller);
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract's observable rule: the call succeeds (ok==true) iff caller == depositorAccount.
        // We assert that if caller != depositorAccount then the call reverted (ok == false).
        // This single assertion is satisfied by the reference for all inputs, and the mutant (which only
        // differs in revert message) will still have the same boolean behavior; however the property we
        // need to observe as a distinguishing difference is the revert reason string. To read the revert
        // reason we must perform a low-level call to collect returned data. We'll do that here by
        // invoking the same call via address(c).call and inspecting the returned revert reason string.

        // Perform low-level call to capture returned data
        bytes memory payload = abi.encodeWithSelector(
            C.setL1BlockValues.selector,
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );

        vm.prank(caller);
        (bool succ, bytes memory data) = address(c).call(payload);

        // For the reference contract, when caller != depositorAccount the revert reason should contain
        // the exact ASCII string: "L1Block: only the depositor account can set L1 block values"
        // We assert that for all callers, if caller != depositorAccount then the low-level call fails
        // and the revert reason matches that exact bytes sequence. This is the universal property.

        address depositor = c.depositorAccount();
        if (caller != depositor) {
            // call must have reverted
            // Build the expected revert string as ABI-encoded Error(string)
            bytes memory expectedPrefix = abi.encodeWithSelector(
                bytes4(keccak256("Error(string)")),
                string(abi.encodePacked("L1Block: only the depositor account can set L1 block values"))
            );
            // succ must be false
            assertTrue(!succ && keccak256(data) == keccak256(expectedPrefix));
        } else {
            // when caller == depositor, call should succeed
            assertTrue(succ);
        }
    }
}
